/* Scroll-driven desktop journey with a native touch and reduced-motion fallback. */
(()=>{
 const root=document.querySelector('#presence');if(!root)return;
 const viewport=root.querySelector('.journey-viewport'),track=root.querySelector('.journey-track'),scenes=[...root.querySelectorAll('.journey-scene')],buttons=[...root.querySelectorAll('[data-step]')],bar=root.querySelector('.journey-progress span'),count=root.querySelector('#journey-count'),cursor=root.querySelector('.journey-cursor');
 const reduced=matchMedia('(prefers-reduced-motion: reduce)'),desktop=matchMedia('(min-width:960px) and (min-height:680px) and (pointer:fine)');
 const clamp=n=>Math.min(1,Math.max(0,n));let active=0,trigger=null,animation=null,centers=[],travel=1,startX=0,progress=0,drag=null,frame=0;
 function status(p){progress=clamp(p);active=Math.round(progress*3);buttons.forEach((b,i)=>i===active?b.setAttribute('aria-current','step'):b.removeAttribute('aria-current'));count.textContent='0'+(active+1)+' / 04';bar.style.transform='scaleX('+(.25+progress*.75)+')';scenes.forEach((s,i)=>s.querySelectorAll('a').forEach(a=>{a.tabIndex=trigger&&i!==active?-1:0;}));}
 function render(p){status(p);const x=startX-travel*progress;gsap.set(track,{x});scenes.forEach((s,i)=>{const d=(centers[i]+x-viewport.clientWidth/2)/scenes[0].offsetWidth,amount=Math.min(Math.abs(d),1);gsap.set(s,{scale:1-amount*.075,rotationY:Math.max(-5,Math.min(5,-d*5)),opacity:1-amount*.45});gsap.set(s.querySelector('.journey-art'),{x:Math.max(-22,Math.min(22,d*22))});});}
 function measure(){centers=scenes.map(s=>s.offsetLeft+s.offsetWidth/2);startX=viewport.clientWidth/2-centers[0];travel=centers[3]-centers[0];}
 function scrollPage(y,immediate=false){const lenis=window.MGL_MOTION?.lenis;if(lenis)lenis.scrollTo(y,{immediate,duration:.75,force:true});else window.scrollTo({top:y,behavior:immediate||reduced.matches?'instant':'smooth'});}
 function go(i){i=Math.max(0,Math.min(3,i));if(trigger)scrollPage(trigger.start+(trigger.end-trigger.start)*i/3);else viewport.scrollTo({left:scenes[i].offsetLeft-(viewport.clientWidth-scenes[i].offsetWidth)/2,behavior:reduced.matches?'instant':'smooth'});}
 buttons.forEach((b,i)=>b.addEventListener('click',()=>go(i)));
 root.addEventListener('keydown',e=>{if(!viewport.contains(e.target)&&!e.target.closest('.journey-steps'))return;let next;if(e.key==='ArrowRight')next=active+1;else if(e.key==='ArrowLeft')next=active-1;else if(e.key==='Home')next=0;else if(e.key==='End')next=3;else return;e.preventDefault();go(next);if(e.target.closest('.journey-steps'))buttons[Math.max(0,Math.min(3,next))].focus({preventScroll:true});});
 viewport.addEventListener('scroll',()=>{if(trigger||frame)return;frame=requestAnimationFrame(()=>{frame=0;const first=scenes[0].offsetLeft-(viewport.clientWidth-scenes[0].offsetWidth)/2;status((viewport.scrollLeft-first)/(scenes[3].offsetLeft-scenes[0].offsetLeft));});},{passive:true});
 viewport.addEventListener('pointerdown',e=>{if(!trigger||e.pointerType!=='mouse'||e.button!==0||e.target.closest('a,button'))return;drag={x:e.clientX,p:trigger.progress};viewport.setPointerCapture(e.pointerId);viewport.classList.add('is-dragging');});
 viewport.addEventListener('pointermove',e=>{if(!trigger)return;const rect=viewport.getBoundingClientRect();cursor.style.display=e.target.closest('a,button')?'none':'block';cursor.style.transform='translate('+Math.min(rect.width-125,Math.max(0,e.clientX-rect.left+15))+'px,'+Math.max(0,e.clientY-rect.top-45)+'px)';if(drag)scrollPage(trigger.start+clamp(drag.p+(drag.x-e.clientX)/travel)*(trigger.end-trigger.start),true);});
 function release(){drag=null;viewport.classList.remove('is-dragging');}viewport.addEventListener('pointerup',release);viewport.addEventListener('pointercancel',release);viewport.addEventListener('lostpointercapture',release);viewport.addEventListener('pointerleave',()=>cursor.style.display='none');
 viewport.addEventListener('wheel',e=>{if(!trigger||Math.abs(e.deltaX)<=Math.abs(e.deltaY))return;const delta=e.deltaX*(e.deltaMode===1?16:e.deltaMode===2?viewport.clientWidth:1);if((trigger.progress<=0&&delta<0)||(trigger.progress>=1&&delta>0))return;e.preventDefault();scrollPage(trigger.start+clamp(trigger.progress+delta/travel)*(trigger.end-trigger.start),true);},{passive:false});
 function setup(){release();trigger?.kill();animation?.kill();trigger=animation=null;root.classList.remove('journey-pinned');cursor.style.display='none';if(window.gsap)gsap.set([track,...scenes,...root.querySelectorAll('.journey-art')],{clearProps:'transform,opacity'});viewport.scrollLeft=0;
  if(desktop.matches&&!reduced.matches&&window.gsap&&window.ScrollTrigger){root.classList.add('journey-pinned');measure();const state={p:0};animation=gsap.to(state,{p:1,ease:'none',onUpdate:()=>render(state.p),scrollTrigger:{id:'mgl-presence-journey',trigger:root,pin:root.querySelector('.journey-shell'),start:'top top',end:()=>'+='+Math.max(travel,innerHeight*2.5),scrub:.55,invalidateOnRefresh:true,onRefresh:()=>{measure();render(state.p);}}});trigger=animation.scrollTrigger;render(trigger.progress);}else status(0);
  window.ScrollTrigger?.refresh();
 }
 desktop.addEventListener('change',setup);reduced.addEventListener('change',setup);setup();document.fonts.ready.then(()=>window.ScrollTrigger?.refresh());
})();
